package main

import("bytes";_ "embed";"encoding/csv";"encoding/json";"fmt";"math";"os";"path/filepath";"strconv";"strings")

//go:embed "acceso chatgpt/GestionSO_Datos.csv"
var embeddedMasterCSV []byte

type CalculatedColumn struct{Name string; Formula string; Percent bool}
type DatasetSettings struct{Decimals int `json:"decimals"`;FontSize int `json:"font_size"`;SOColumn int `json:"so_column"`;JoinExcelColumn string `json:"join_excel_column"`;FormulaTitle string `json:"formula_title"`;Formula string `json:"formula"`;SubtotalColumn string `json:"subtotal_column"`;SubtotalEnabled bool `json:"subtotal_enabled"`;ColumnTitles map[string]string `json:"column_titles"`;ColumnOrder []string `json:"column_order"`;MaxColumns int `json:"max_columns"`;VisibleColumns []string `json:"visible_columns"`;ColumnDecimals map[string]int `json:"column_decimals"`;SubtotalColumns []string `json:"subtotal_columns"`;ColumnPercent map[string]bool `json:"column_percent"`;HighlightNegative map[string]bool `json:"highlight_negative"`;ColumnTypes map[string]string `json:"column_types"`;CalculatedColumns []CalculatedColumn `json:"calculated_columns"`}
func defaultDatasetSettings()DatasetSettings{return DatasetSettings{Decimals:2,FontSize:10,SOColumn:5,JoinExcelColumn:"SKU",FormulaTitle:"CALCULADA",SubtotalEnabled:false,ColumnTitles:map[string]string{},MaxColumns:20,ColumnDecimals:map[string]int{},ColumnPercent:map[string]bool{},HighlightNegative:map[string]bool{},ColumnTypes:map[string]string{}}}
func datasetSettingsPath()string{if d,e:=os.UserConfigDir();e==nil{return filepath.Join(d,"GestionSO V57","dataset.txt")};return filepath.Join(os.TempDir(),"GestionSO-V57-dataset.txt")}
func loadDatasetSettings()DatasetSettings{s:=defaultDatasetSettings();if b,e:=os.ReadFile(datasetSettingsPath());e==nil&&json.Unmarshal(b,&s)==nil{datasetSettingsNormalize(&s);return s};return s}
func datasetSettingsNormalize(s *DatasetSettings){if s.Decimals<0||s.Decimals>8{s.Decimals=2};if s.FontSize<8||s.FontSize>32{s.FontSize=10};if s.SOColumn<1||s.SOColumn>1024{s.SOColumn=5};if s.MaxColumns<1||s.MaxColumns>100{s.MaxColumns=20};if s.ColumnTitles==nil{s.ColumnTitles=map[string]string{}};if s.ColumnDecimals==nil{s.ColumnDecimals=map[string]int{}};if s.ColumnPercent==nil{s.ColumnPercent=map[string]bool{}};if s.HighlightNegative==nil{s.HighlightNegative=map[string]bool{}};if s.ColumnTypes==nil{s.ColumnTypes=map[string]string{}}}
func saveDatasetSettings(s DatasetSettings)error{datasetSettingsNormalize(&s);p:=datasetSettingsPath();if e:=os.MkdirAll(filepath.Dir(p),0755);e!=nil{return e};b,e:=json.MarshalIndent(s,"","  ");if e!=nil{return e};return os.WriteFile(p,b,0644)}

type DatasetColumn struct{ID,Title,Source string;Type ValueType;Width int;Visible bool}
type DatasetRecord struct{SO string;Values map[string]MemoryValue}
type MemoryDataset struct{Columns []DatasetColumn;Records []DatasetRecord;CSVRows,Enriched,DuplicateSO int;SourceFiles []string}
type csvMaster struct{Headers []string;ByKey map[string]map[string]string}
func normalizeJoinKey(v string)string{return strings.ToUpper(strings.TrimSpace(v))}
func datasetColumnKey(c DatasetColumn)string{return c.Source+"|"+c.Title}
func datasetColumnDisplayTitle(c DatasetColumn)string{if t:=strings.TrimSpace(appSettings.ColumnTitles[datasetColumnKey(c)]);t!=""{return t};return c.Title}
func datasetColumnDecimals(c DatasetColumn)int{if d,ok:=appSettings.ColumnDecimals[datasetColumnKey(c)];ok&&d>=0&&d<=8{return d};return appSettings.Decimals}
func datasetColumnIsPercent(c DatasetColumn)bool{return appSettings.ColumnPercent[datasetColumnKey(c)]}
func datasetColumnHighlightNegative(c DatasetColumn)bool{return appSettings.HighlightNegative[datasetColumnKey(c)]}
func parseConfiguredType(v string)ValueType{switch strings.ToLower(strings.TrimSpace(v)){case "entero","integer":return ValueNumber;case "decimal","number","numero":return ValueNumber;case "fecha","date":return ValueDate;case "porcentaje","percent":return ValueNumber};return ValueEmpty}
func applyConfiguredColumnType(c DatasetColumn)DatasetColumn{if t:=parseConfiguredType(appSettings.ColumnTypes[datasetColumnKey(c)]);t!=ValueEmpty{c.Type=t};return c}

func loadMasterCSV(path string)(*csvMaster,string,error){data:=embeddedMasterCSV;source:="CSV maestro integrado: GestionSO_Datos.csv";if path!=""{if b,e:=os.ReadFile(path);e==nil{data=b;source=path}}else{var cs []string;if x,e:=os.Executable();e==nil{cs=append(cs,filepath.Join(filepath.Dir(x),"GestionSO_Datos.csv"))};if x,e:=os.Getwd();e==nil{cs=append(cs,filepath.Join(x,"GestionSO_Datos.csv"),filepath.Join(x,"acceso chatgpt","GestionSO_Datos.csv"))};for _,p:=range cs{if b,e:=os.ReadFile(p);e==nil{data=b;source=p;break}}};r:=csv.NewReader(bytes.NewReader(data));r.Comma=';';r.FieldsPerRecord=-1;rows,e:=r.ReadAll();if e!=nil{return nil,source,e};if len(rows)==0{return nil,source,fmt.Errorf("CSV maestro vacío")};h:=make([]string,len(rows[0]));ki:=-1;for i,x:=range rows[0]{h[i]=strings.TrimPrefix(x,"\ufeff");if strings.EqualFold(strings.TrimSpace(h[i]),"CLAVE"){ki=i}};if ki<0{return nil,source,fmt.Errorf("CSV maestro sin columna CLAVE")};m:=&csvMaster{Headers:h,ByKey:map[string]map[string]string{}};for _,row:=range rows[1:]{if ki>=len(row){continue};k:=normalizeJoinKey(row[ki]);if k==""{continue};v:=map[string]string{};for i,x:=range h{if i<len(row){v[x]=strings.TrimSpace(row[i])}};m.ByKey[k]=v};return m,source,nil}

func csvHeaderTypes(m *csvMaster)map[string]ValueType{out:=map[string]ValueType{};if m==nil{return out};for _,h:=range m.Headers{out[h]=ValueText};for _,row:=range m.ByKey{for h,raw:=range row{if raw==""{continue};t:=inferValueType(raw);if t==ValueNumber{out[h]=ValueNumber}}};return out}

func BuildMemoryDataset(docs []*xlsxDoc,s DatasetSettings)(*MemoryDataset,error){if len(docs)==0{return nil,fmt.Errorf("no hay archivos XLSX seleccionados")};m,_,e:=loadMasterCSV("");if e!=nil{return nil,e};ds:=&MemoryDataset{CSVRows:len(m.ByKey)};ids:=map[string]string{};add:=func(t,src string,typ ValueType)string{t=strings.TrimSpace(t);k:=strings.ToLower(src+"|"+t);if x,ok:=ids[k];ok{return x};x:=fmt.Sprintf("D%03d",len(ds.Columns)+1);c:=DatasetColumn{ID:x,Title:t,Source:src,Type:typ,Width:140,Visible:true};c=applyConfiguredColumnType(c);ds.Columns=append(ds.Columns,c);ids[k]=x;return x};seenLines:=map[string]bool{}
	csvTypes:=csvHeaderTypes(m);for _,h:=range m.Headers{add(h,"CSV",csvTypes[h])}
	for _,doc:=range docs{if doc==nil||doc.Memory==nil{continue};for _,sh:=range doc.Memory.Sheets{soID,joinID,itemID:="","","";mapID:=map[string]string{};for _,c:=range sh.Columns{id:=add(c.Title,"XLSX",c.Type);mapID[c.ID]=id;if c.Index==s.SOColumn-1{soID=c.ID};if strings.EqualFold(strings.TrimSpace(c.Title),strings.TrimSpace(s.JoinExcelColumn)){joinID=c.ID};if strings.EqualFold(strings.TrimSpace(c.Title),"ITEM"){itemID=c.ID}};if soID==""{continue};for _,row:=range sh.Rows{v,ok:=row.Values[soID];if !ok||strings.TrimSpace(v.Raw)==""{continue};lineKey:="";if itemID!=""{if item,ok:=row.Values[itemID];ok&&strings.TrimSpace(item.Raw)!=""{lineKey=normalizeJoinKey(v.Raw)+"\x1f"+normalizeJoinKey(item.Raw)}};if lineKey!=""{if seenLines[lineKey]{ds.DuplicateSO++;continue};seenLines[lineKey]=true};rec:=DatasetRecord{SO:v.Raw,Values:map[string]MemoryValue{}};join:="";for old,newID:=range mapID{if x,ok:=row.Values[old];ok{x.ColumnID=newID;rec.Values[newID]=x;if old==joinID{join=x.Raw}}};if item,ok:=m.ByKey[normalizeJoinKey(join)];ok{ds.Enriched++;for _,h:=range m.Headers{raw:=item[h];if raw==""{continue};id:=add(h,"CSV",csvTypes[h]);rec.Values[id]=makeMemoryValue(id,raw)}};ds.Records=append(ds.Records,rec)}}}
	if len(ds.Records)==0{return nil,fmt.Errorf("no se encontraron filas con SO en la columna configurada N°%d",s.SOColumn)}
	ensureCalculatedDatasetColumns(ds,s);return ds,nil}

func ensureCalculatedDatasetColumns(ds *MemoryDataset,s DatasetSettings){if ds==nil{return};ensure:=func(name string)DatasetColumn{for _,c:=range ds.Columns{if c.Source=="CALCULADA"&&strings.EqualFold(c.Title,name){return c}};c:=DatasetColumn{ID:fmt.Sprintf("D%03d",len(ds.Columns)+1),Title:name,Source:"CALCULADA",Type:ValueNumber,Width:150,Visible:true};ds.Columns=append(ds.Columns,c);return c};if strings.TrimSpace(s.FormulaTitle)!=""&&strings.TrimSpace(s.Formula)!=""{ensure(strings.TrimSpace(s.FormulaTitle))};for _,cc:=range s.CalculatedColumns{if strings.TrimSpace(cc.Name)!=""&&strings.TrimSpace(cc.Formula)!=""{ensure(strings.TrimSpace(cc.Name))}}}

func(e *MemoryDataset)columnByTitle(t string)(DatasetColumn,bool){for _,c:=range e.Columns{if strings.EqualFold(strings.TrimSpace(c.Title),strings.TrimSpace(t))||strings.EqualFold(strings.TrimSpace(datasetColumnDisplayTitle(c)),strings.TrimSpace(t)){return c,true}};return DatasetColumn{},false}
func evaluateFormula(expr string,r DatasetRecord,cols []DatasetColumn)(float64,bool){vals:=map[string]float64{};for _,c:=range cols{if v,ok:=r.Values[c.ID];ok&&(v.Type==ValueNumber||v.Type==ValueDate){n:=v.Number;title:=strings.ToLower(strings.TrimSpace(c.Title));vals[title]=n;vals[strings.ToLower(strings.TrimSpace(c.Source+":"+c.Title))]=n;if c.Source=="CSV"{vals["csv:"+title]=n}}};p:=&formulaParser{s:expr,values:vals};v,ok:=p.expr();p.skip();return v,ok&&p.pos==len(p.s)}
type formulaParser struct{s string;values map[string]float64;pos int};func(p *formulaParser)skip(){for p.pos<len(p.s)&&(p.s[p.pos]==' '||p.s[p.pos]=='\t'){p.pos++}};func(p *formulaParser)expr()(float64,bool){a,ok:=p.term();if !ok{return 0,false};for{p.skip();if p.pos>=len(p.s){return a,true};o:=p.s[p.pos];if o!='+'&&o!='-'{return a,true};p.pos++;b,ok:=p.term();if !ok{return 0,false};if o=='+'{a+=b}else{a-=b}}};func(p *formulaParser)term()(float64,bool){a,ok:=p.factor();if !ok{return 0,false};for{p.skip();if p.pos>=len(p.s){return a,true};o:=p.s[p.pos];if o!='*'&&o!='/'{return a,true};p.pos++;b,ok:=p.factor();if !ok{return 0,false};if o=='*'{a*=b}else{if b==0{return 0,false};a/=b}}};func(p *formulaParser)factor()(float64,bool){p.skip();if p.pos>=len(p.s){return 0,false};if p.s[p.pos]=='(' {p.pos++;v,ok:=p.expr();p.skip();if p.pos>=len(p.s)||p.s[p.pos]!=')'{return 0,false};p.pos++;return v,ok};st:=p.pos;if p.s[p.pos]=='['{if e:=strings.IndexByte(p.s[st:],']');e>=0{e+=st;key:=strings.ToLower(strings.TrimSpace(p.s[st+1:e]));p.pos=e+1;v,ok:=p.values[key];return v,ok}};for p.pos<len(p.s)&&((p.s[p.pos]>='0'&&p.s[p.pos]<='9')||p.s[p.pos]=='.'||p.s[p.pos]==','){p.pos++};if p.pos>st{v,e:=strconv.ParseFloat(strings.ReplaceAll(p.s[st:p.pos],",","."),64);return v,e==nil};return 0,false}
func applyDatasetFormula(ds *MemoryDataset,s DatasetSettings){if ds==nil{return};ensureCalculatedDatasetColumns(ds,s);if s.Formula!=""&&s.FormulaTitle!=""{if c,ok:=ds.columnByTitle(s.FormulaTitle);ok{for i:=range ds.Records{if v,ok:=evaluateFormula(s.Formula,ds.Records[i],ds.Columns);ok{ds.Records[i].Values[c.ID]=MemoryValue{ColumnID:c.ID,Type:ValueNumber,Number:v,Raw:formatDatasetNumber(v,datasetColumnDecimals(c))}}}}};for _,cc:=range s.CalculatedColumns{c,ok:=ds.columnByTitle(cc.Name);if !ok{continue};for i:=range ds.Records{if v,ok:=evaluateFormula(cc.Formula,ds.Records[i],ds.Columns);ok{if cc.Percent{v*=100};ds.Records[i].Values[c.ID]=MemoryValue{ColumnID:c.ID,Type:ValueNumber,Number:v,Raw:formatDatasetNumber(v,datasetColumnDecimals(c))}}}}}
func formatDatasetNumber(v float64,d int)string{if d<0{d=0};if d>8{d=8};if math.IsNaN(v)||math.IsInf(v,0){return ""};return strconv.FormatFloat(v,'f',d,64)}
